import type { CardCheck } from '@/lib/flashcard-check-core'

/**
 * Card-check questions for the cards of `mcat-genetics-evolution-natural-selection-mcat`: one per card, keyed by the
 * card's exact front text. Each asks the student to use the card's idea in a
 * new situation. Gate: scripts/flashcard-checks/validate.ts.
 */
const r = String.raw

export const checks: Record<string, CardCheck> = {
  [r`Why is antibiotic resistance a demonstration of natural selection?`]: {
    question: r`A lab freezes a sample of a bacterial culture, then treats the rest with an antibiotic. Nearly all cells die, and the survivors regrow as a resistant culture. Sequencing the frozen, never-treated sample finds the same resistance allele in about 1 cell per million. What does this show about the drug's role?`,
    options: [r`The drug triggered resistance mutations in cells it touched`, r`The drug taught surviving cells to tolerate it over time`, r`The drug favored rare resistant cells that already existed`, r`The drug raised the mutation rate only at the target gene`],
    correctAnswer: 2,
    explanation: r`The allele was present before any exposure, so the drug only removed susceptible cells and left the existing resistant ones to multiply. Saying the drug triggered mutations, trained cells, or raised a targeted mutation rate all treat the drug as the creator of resistance, which the frozen sample rules out.`,
  },
  [r`What are prezygotic vs. postzygotic isolating mechanisms?`]: {
    question: r`Pollen from one lily species lands on a second species. The pollen tube grows, a sperm fuses with the egg, and the embryo divides a few times and then aborts. How should this barrier be classified?`,
    options: [r`Prezygotic, because no viable seed is ever produced`, r`Prezygotic, because the pollen tube is a mating structure`, r`Postzygotic, because a zygote forms but fails to develop`, r`Postzygotic, because the pollen fails to reach the ovule`],
    correctAnswer: 2,
    explanation: r`The dividing line is fertilization: here a zygote forms and then dies, so the barrier is postzygotic (hybrid inviability). Calling it prezygotic because no seed results confuses the final outcome with the stage of failure, and the pollen clearly did reach and fertilize the ovule.`,
  },
  [r`Distinguish homologous and analogous structures.`]: {
    question: r`Octopuses and humans both have camera-type eyes with a lens and retina. Their last common ancestor had only a simple patch of light-sensitive cells, and the two eyes develop from different embryonic tissues. These eyes are best described as:`,
    options: [r`Homologous structures produced by divergent evolution`, r`Analogous structures produced by convergent evolution`, r`Homologous structures produced by convergent evolution`, r`Analogous structures produced by divergent evolution`],
    correctAnswer: 1,
    explanation: r`The camera eye was not inherited from the shared ancestor; it arose separately in each lineage under similar selection, which makes the eyes analogous and the process convergent. Homologous structures require inheritance from a common ancestor, and analogy pairs with convergence, not divergence.`,
  },
  [r`What is inclusive fitness / kin selection?`]: {
    question: r`A bird gives up breeding for a season, which costs it 2 offspring of its own, and instead helps its full sister raise 5 extra chicks she could not have raised alone. According to Hamilton's rule, is this helping favored?`,
    options: [r`Yes, because 0.5 × 5 = 2.5 is greater than the cost of 2`, r`No, because 0.25 × 5 = 1.25 is less than the cost of 2`, r`Yes, because the benefit of 5 is greater than the cost of 2`, r`No, because 0.5 × 2 = 1 is less than the benefit of 5`],
    correctAnswer: 0,
    explanation: r`Full siblings have r = 0.5, so rB = 0.5 × 5 = 2.5, which exceeds C = 2 and satisfies rB > C. Using 0.25 applies the half-sibling value, comparing 5 with 2 directly leaves out relatedness, and multiplying r by the cost puts the weighting on the wrong side of the rule.`,
  },
  [r`What does fitness mean in evolutionary terms?`]: {
    question: r`In one meadow, plants of genotype P live a single season and leave an average of 20 offspring that grow up and reproduce. Plants of genotype Q live ten seasons and leave an average of 5 offspring that grow up and reproduce. Which genotype has the higher evolutionary fitness?`,
    options: [r`Genotype P, because it leaves more reproducing offspring`, r`Genotype Q, because it survives for many more seasons`, r`Genotype Q, because it invests more in each offspring`, r`Genotype P, because it finishes its life cycle faster`],
    correctAnswer: 0,
    explanation: r`Fitness is the contribution of alleles to the next generation, so 20 reproducing offspring beats 5 no matter how long each parent lives. Longevity and investment per offspring count only if they raise that number, and a fast life cycle is not the reason by itself.`,
  },
  [r`Contrast allopatric and sympatric speciation.`]: {
    question: r`Case 1: rising seas split a lizard population onto two islands, and the two groups later become separate species. Case 2: in a single meadow, a tetraploid plant arises among its diploid parents and can no longer breed with them. How are the two speciation events classified?`,
    options: [r`The first is sympatric and the second is allopatric`, r`The first is allopatric and the second is sympatric`, r`Both are allopatric, since isolation is involved`, r`Both are sympatric, since one species is involved`],
    correctAnswer: 1,
    explanation: r`Allopatric speciation begins with a geographic barrier, such as the sea between the islands, while sympatric speciation happens within one area, as with the polyploid plant in the meadow. Both cases involve reproductive isolation and one starting species, so neither of those facts tells the two modes apart.`,
  },
  [r`Contrast gradualism and punctuated equilibrium.`]: {
    question: r`In a continuous series of sediments, a trilobite lineage shows the number of ribs rising by small, steady steps, about one rib every 300,000 years across 3 million years, with every intermediate form present. Which model of evolutionary tempo does this record support?`,
    options: [r`Gradualism, because change is slow and continuous`, r`Punctuated equilibrium, because it spans millions of years`, r`Punctuated equilibrium, because one lineage changes form`, r`Gradualism, because long stasis separates rapid bursts`],
    correctAnswer: 0,
    explanation: r`Steady small steps with all intermediates present is the gradualist pattern. Punctuated equilibrium is defined by long stasis broken by brief bursts, not by the total time involved or by the mere fact of change, and stasis with bursts is the opposite of gradualism.`,
  },
  [r`What is sexual selection?`]: {
    question: r`In a widowbird, males whose tails were experimentally lengthened attracted more nesting females than control males, although the longer tails made flight slower and more costly. Which process best explains the evolution of long tails in males?`,
    options: [r`Natural selection acting through predator escape`, r`Stabilizing selection acting around a flight optimum`, r`Sexual selection acting through female mate choice`, r`Kin selection acting through help given to relatives`],
    correctAnswer: 2,
    explanation: r`The tail raises mating success while lowering flight performance, which is the mark of sexual selection by mate choice opposing survival. Predator escape and a flight optimum would both favor shorter tails, and nothing here involves help directed at relatives.`,
  },
  [r`Why do recessive deleterious alleles persist in populations?`]: {
    question: r`A recessive lethal allele persists in a large population. Among every 10,000 newborns, 1 is an affected homozygote (carrying 2 copies) and 198 are healthy carriers (1 copy each). About what share of the allele's copies sit in carriers, and what follows?`,
    options: [r`About 50%, so selection removes half the copies per generation`, r`About 99%, so selection removes very few copies per generation`, r`About 2%, so selection removes nearly all copies per generation`, r`About 66%, so selection removes a third of copies per generation`],
    correctAnswer: 1,
    explanation: r`Carriers hold 198 of the 200 copies, or 99%, and carriers are phenotypically normal, so selection only reaches the 2 copies in the homozygote. The other figures miscount the copies; the key point is that selection acts on the homozygous phenotype and almost all copies are hidden in heterozygotes.`,
  },
  [r`Hardy-Weinberg equilibrium requires all of the following EXCEPT:`]: {
    question: r`A very large, isolated population mates at random and has a negligible mutation rate. Over 20 generations the frequency of allele A climbs steadily from 0.3 to 0.5. Which Hardy-Weinberg assumption is most likely being violated?`,
    options: [r`The assumption that mates pair without regard to genotype`, r`The assumption that no migrants enter from other populations`, r`The assumption that the population is too large for drift`, r`The assumption that no genotype has a survival advantage`],
    correctAnswer: 3,
    explanation: r`With isolation, random mating, large size and no mutation all stated, the only remaining cause of a steady directional change in allele frequency is natural selection. Random mating, absence of migration and large size are described as holding, so those assumptions are not the ones broken.`,
  },
  [r`Frequency-dependent selection means fitness depends on:`]: {
    question: r`A scale-eating fish has left-mouthed and right-mouthed forms. Prey fish learn to guard the side attacked by whichever form is more common. In a year when left-mouthed fish make up only 30% of the population, what is expected?`,
    options: [r`Left-mouthed fish have lower fitness and fall in frequency`, r`Both forms have equal fitness and their frequencies stay fixed`, r`Left-mouthed fish have higher fitness and rise in frequency`, r`Right-mouthed fish have higher fitness and reach fixation`],
    correctAnswer: 2,
    explanation: r`Fitness here depends on how common a form is: prey guard against the common right-mouthed form, so the rare left-mouthed form feeds better and increases. The advantage fades as it becomes common, which is why neither form declines to loss or reaches fixation and the fitnesses are not equal at 30%.`,
  },
  [r`Group selection is controversial because:`]: {
    question: r`A colony of microbes secretes a costly enzyme that frees nutrients for every cell nearby, so colonies of producers grow well. A mutant that makes no enzyme arises inside one such colony. What is the expected outcome within that colony?`,
    options: [r`The mutant spreads, since it shares the benefit at no cost`, r`The mutant is lost, since selection favors the group's good`, r`The mutant is lost, since producers outgrow it in the colony`, r`The mutant spreads, since the enzyme poisons producer cells`],
    correctAnswer: 0,
    explanation: r`Inside the colony the mutant gets the nutrients without paying to make the enzyme, so individual selection favors it quickly, which is why group-benefit explanations are doubted. Selection does not act for the good of the group, producers do not outgrow a free rider beside them, and the enzyme is costly rather than poisonous.`,
  },
  [r`Artificial selection differs from natural selection in that humans:`]: {
    question: r`Researchers allowed only the tamest 10% of captive foxes to breed in each generation, and after 40 generations the foxes behaved much like dogs. Which feature makes this artificial rather than natural selection?`,
    options: [r`People decided which trait determined who bred`, r`The foxes were housed in cages rather than wild`, r`The change took decades rather than millennia`, r`The trait involved behavior rather than anatomy`],
    correctAnswer: 0,
    explanation: r`Artificial selection is defined by the selecting agent: humans chose tameness as the trait that earned reproduction. Captivity, speed and the kind of trait do not define it, since natural selection can also act in captivity, act quickly, and act on behavior.`,
  },
  [r`Sympatric speciation occurs:`]: {
    question: r`Two forms of a stick insect live on two shrub species that grow intermixed on one hillside, and the forms rarely interbreed. A researcher proposes that they diverged by sympatric speciation. Which finding would most undermine that proposal?`,
    options: [r`The forms diverged while confined to separate valleys`, r`The forms prefer to rest and feed on different shrubs`, r`The forms mate mainly on the shrub they grew up on`, r`The forms differ in color to match their own shrubs`],
    correctAnswer: 0,
    explanation: r`Sympatric speciation means divergence without geographic separation, so evidence of an earlier period in separate valleys would make the divergence allopatric. Different host preference, mating on the home shrub and matching colors are all biological isolating factors that fit a sympatric origin.`,
  },
  [r`Which type of selection favors individuals at both extremes of a trait distribution?`]: {
    question: r`In a salmon population, large males win fights for females and sire an average of 6 offspring, small males sneak matings and sire an average of 5, and medium males can do neither well and sire an average of 1. Which mode of selection is acting on male body size?`,
    options: [r`Directional selection, since the largest males do the best`, r`Stabilizing selection, since medium males sit near the mean`, r`Directional selection, since small males beat medium males`, r`Disruptive selection, since both extremes beat the middle`],
    correctAnswer: 3,
    explanation: r`Both tails of the size distribution have high fitness and the intermediate has low fitness, which defines disruptive selection. Directional selection would favor only one extreme, and stabilizing selection would give the medium males the highest fitness, not the lowest.`,
  },
  [r`Rapid diversification of a single lineage into many niche-specialized species is {{c1::adaptive radiation}}.`]: {
    question: r`After a mass extinction removes the large marine reptiles, the fossil record shows one surviving fish lineage giving rise, in a geologically short time, to many species with different body forms and diets. What is this pattern, and what set it off?`,
    options: [r`Convergent evolution, triggered by similar habitats`, r`Adaptive radiation, triggered by newly vacant niches`, r`Adaptive radiation, triggered by a higher mutation rate`, r`Stabilizing selection, triggered by reduced competition`],
    correctAnswer: 1,
    explanation: r`One lineage diversifying rapidly into many niche specialists is adaptive radiation, and the trigger is ecological opportunity left by the extinction. Convergence involves unrelated lineages becoming similar, a raised mutation rate is not the cause, and stabilizing selection would hold forms constant.`,
  },
  [r`Convergent vs divergent evolution: classify dolphin/shark body forms versus Darwin's finches.`]: {
    question: r`Sugar gliders (marsupials) and flying squirrels (placental mammals) each evolved a gliding membrane independently. Separately, about 30 Hawaiian silversword plant species with very different growth forms all descend from one colonizing ancestor. Classify each pattern.`,
    options: [r`The gliders are divergent; the silverswords are convergent`, r`The gliders are convergent; the silverswords are convergent`, r`The gliders are convergent; the silverswords are divergent`, r`The gliders are divergent; the silverswords are divergent`],
    correctAnswer: 2,
    explanation: r`Distantly related mammals arriving at the same gliding form under similar pressures is convergence, giving analogous membranes. One ancestor producing many different descendant forms is divergence. Swapping the labels reverses which pattern starts from separate ancestors and which starts from a shared one.`,
  },
  [r`The biological species concept defines species by {{c1::reproductive isolation}} — a criterion inapplicable to asexual taxa and fossils.`]: {
    question: r`Bird populations A and B look almost identical but never interbreed where their ranges overlap. Populations C and D look very different but interbreed freely and produce fertile offspring. Under the biological species concept, how are they classified?`,
    options: [r`A and B are a single species; C and D are separate species`, r`A and B are a single species; C and D are a single species`, r`A and B are separate species; C and D are separate species`, r`A and B are separate species; C and D are a single species`],
    correctAnswer: 3,
    explanation: r`The biological species concept uses reproductive isolation as the test, not appearance. A and B do not interbreed, so they are separate species, while C and D exchange genes freely and are one. The options that group A with B or split C from D are sorting by looks, which is the morphological concept.`,
  },
  [r`Vestigial structures like the whale pelvis argue for evolution because {{c1::they are reduced remnants of functional ancestral structures}}.`]: {
    question: r`Boas and pythons have tiny bones embedded in the body wall near the tail. The bones match the pelvis and thigh bone of lizards in position and development but play no part in movement. What do these bones most directly indicate?`,
    options: [r`Snakes are developing hind limbs for later use on land`, r`Snakes and lizards evolved their pelvic bones separately`, r`Snakes rely on these bones as their chief means of travel`, r`Snakes descend from ancestors with working hind limbs`],
    correctAnswer: 3,
    explanation: r`Reduced structures that keep clear homology with functional versions in relatives are vestigial remnants of an ancestral structure, here the hind limbs. Evolution does not build structures for future use, the matching position and development argue against separate origins, and the bones are stated to have no role in movement.`,
  },
  [r`The molecular clock infers divergence times from {{c1::the roughly constant accumulation rate of neutral sequence differences}}.`]: {
    question: r`Two lizard species known from fossils to have split 10 million years ago differ at 20 neutral sites in a gene. Two other species differ at 50 neutral sites in the same gene. Assuming a constant rate, when did the second pair diverge?`,
    options: [r`About 25 million years ago`, r`About 100 million years ago`, r`About 4 million years ago`, r`About 50 million years ago`],
    correctAnswer: 0,
    explanation: r`The calibration gives 20 differences per 10 million years, or 2 per million years, so 50 differences correspond to 50 ÷ 2 = 25 million years. The answer of 100 multiplies by the rate, 4 inverts the ratio, and 50 simply reads the number of differences as millions of years.`,
  },
  [r`Biogeographic evidence: why do oceanic islands host endemic species that resemble the nearest mainland forms?`]: {
    question: r`A remote volcanic island has many bird and insect species found nowhere else, but no native frogs or land mammals, even though frogs introduced by people thrive there. Which explanation best fits this pattern?`,
    options: [r`Only good dispersers reached the island and then diverged`, r`The island climate cannot support frogs or land mammals`, r`The frogs and mammals once present were outcompeted there`, r`Each species arose in place to suit the island's habitat`],
    correctAnswer: 0,
    explanation: r`Oceanic islands are stocked by colonists that can cross open sea, such as birds and insects, whose descendants then diverge into endemic forms; frogs and land mammals rarely make the crossing. The success of introduced frogs rules out an unsuitable climate, and origin in place would not predict the missing groups.`,
  },
  [r`How does phyletic gradualism differ from punctuated equilibrium in what each predicts of the fossil record?`]: {
    question: r`A drill core recovers a complete, finely layered sediment sequence with no gaps, full of snail fossils. If the snail lineage evolved as punctuated equilibrium predicts, what should the core show?`,
    options: [r`A smooth series of intermediates spread through every layer`, r`Mostly unchanged forms, with new forms arising in thin layers`, r`Mostly intermediates, with stable forms found in thin layers`, r`No change of any kind, since a complete record has no gaps`],
    correctAnswer: 1,
    explanation: r`Punctuated equilibrium predicts long stasis, so most layers hold unchanging forms, with change packed into brief intervals that occupy thin layers. A smooth series of intermediates is the gradualist prediction, and a complete record does not remove change, it only removes gaps as an excuse for abruptness.`,
  },
  [r`Reinforcement predicts that prezygotic barriers become {{c1::stronger in sympatry than in allopatry}}.`]: {
    question: r`Two fruit fly species produce sterile hybrids. Females of species 1 are collected from population A, which lives alongside species 2, and from population B, which lives far from it. Each is offered males of species 2. What does reinforcement predict?`,
    options: [r`B females reject species 2 males more often than A females`, r`A females and B females reject species 2 males equally often`, r`A females accept species 2 males more often than their own`, r`A females reject species 2 males more often than B females`],
    correctAnswer: 3,
    explanation: r`Where the species overlap, females that mismate waste their reproduction on sterile hybrids, so selection sharpens mate discrimination there: prezygotic isolation is stronger in sympatry than in allopatry. Far from species 2 there is no such selection, so B females should be less choosy, not more or equally so.`,
  },
  [r`Punctuated equilibrium describes {{c1::long morphological stasis interrupted by rapid speciation events}} in the fossil record.`]: {
    question: r`A fossil species stays unchanged through 4 million years of continuously deposited rock and is then replaced abruptly by a descendant species, with no intermediates found. Under punctuated equilibrium, why are the intermediates missing?`,
    options: [r`The change occurred in one generation by a single mutation`, r`The change occurred quickly in a small, local population`, r`The rock layers holding the intermediates were eroded away`, r`The intermediate forms lacked hard parts that could fossilize`],
    correctAnswer: 1,
    explanation: r`Punctuated equilibrium places change in brief speciation episodes, often in small peripheral populations, so few intermediates exist to be preserved. It does not claim single-generation jumps, and with continuous deposition and fossilizable relatives, erosion or soft bodies are not the explanation.`,
  },
  [r`Character displacement: two species differ MORE where their ranges overlap than where they live apart. Why?`]: {
    question: r`Finch species X has a mean beak depth of 10 mm on islands where it lives alone, and species Y also averages 10 mm where it lives alone. On an island where both live and compete for seeds, what does character displacement predict?`,
    options: [r`Beaks near 8 mm in one species and near 12 mm in the other`, r`Beaks near 10 mm in both species, as on the solo islands`, r`Beaks near 12 mm in both species, as each tracks large seeds`, r`Beaks near 8 mm in both species, as each tracks small seeds`],
    correctAnswer: 0,
    explanation: r`Competition where the species overlap selects against individuals that use the same seeds, so the two species diverge and differ more in sympatry than apart. Staying at 10 mm ignores the competition, and both species shifting the same way would keep them competing for the same seeds.`,
  },
  [r`Direct observational evidence of evolution includes {{c1::antibiotic and pesticide resistance evolving within human lifetimes}}.`]: {
    question: r`In 1946 a standard dose of DDT killed 99% of a mosquito population. By 1960 the same dose killed 20%, and preserved samples from each year show a resistance allele rising in frequency. How does this evidence for evolution differ from fossil evidence?`,
    options: [r`The change it documents spans far longer periods of time`, r`The allele frequency change was recorded as it happened`, r`The evidence rests on comparing anatomy across species`, r`The evidence depends on dating layers of sedimentary rock`],
    correctAnswer: 1,
    explanation: r`Pesticide resistance is evolution observed directly within a human lifetime, with allele frequencies measured across the years. Fossil evidence is the kind that covers long time spans, relies on anatomical comparison and needs dated rock layers, and from it past change is inferred rather than watched.`,
  },
  [r`The handicap principle holds that costly ornaments are honest signals because {{c1::only high-quality males can survive while bearing the cost}}.`]: {
    question: r`In a fish species, males display a red spot. Researchers find the pigment costs nothing to make and that weak, parasitized males show spots as bright as healthy males do. Under the handicap principle, what follows about the spot as a signal?`,
    options: [r`It is honest, since females already prefer the bright males`, r`It is honest, since every male can afford to display the spot`, r`It is unreliable, since pigment traits cannot be inherited`, r`It is unreliable, since weak males can show it just as well`],
    correctAnswer: 3,
    explanation: r`A signal is honest only when its cost keeps low-quality males from producing it; a free spot that weak males show equally well tells a female nothing. Existing female preference does not make it honest, being affordable to all is exactly the problem, and heritability of pigment is not the issue.`,
  },
  [r`The selection mode whose trait-distribution graph shows the peak shifting toward one extreme over generations is {{c1::directional selection}}.`]: {
    question: r`A histogram of wing length in a swallow population nesting beside a highway had a single peak at 110 mm thirty years ago. Today the histogram has the same shape, but the peak sits at 106 mm; shorter-winged birds dodge traffic better. Which mode of selection is this?`,
    options: [r`Stabilizing selection, since the curve still has a single peak`, r`Disruptive selection, since the old mean is now less common`, r`Directional selection, since the peak moved toward one extreme`, r`Stabilizing selection, since the longest wings were removed`],
    correctAnswer: 2,
    explanation: r`A whole distribution shifting toward one tail is directional selection. Stabilizing selection would keep the mean and narrow the curve, and disruptive selection would produce two peaks; removal of one extreme only, with a moving mean, is not stabilizing.`,
  },
  [r`The selection mode whose graph keeps the same mean but narrows the curve is {{c1::stabilizing selection}}.`]: {
    question: r`A fly larva lives inside a plant gall. Wasps kill most larvae in small galls and birds eat most larvae in large galls, so larvae in medium galls survive best. Gall size is heritable. How should the distribution of gall size change over generations?`,
    options: [r`The mean stays the same and the curve becomes wider`, r`The mean stays the same and the curve becomes narrower`, r`The mean shifts upward and the curve keeps its width`, r`The mean stays the same and the curve gains two peaks`],
    correctAnswer: 1,
    explanation: r`Both extremes are removed and the intermediate is favored, which is stabilizing selection: the mean holds and the variance shrinks. A wider curve or two peaks would require the extremes to do well, and a shifted mean would require only one extreme to be penalized.`,
  },
  [r`Why does polyploidy produce essentially instantaneous speciation in plants?`]: {
    question: r`A diploid plant has 2n = 14. A tetraploid with 28 chromosomes arises from it and is crossed back to a diploid. How many chromosomes does the offspring have, and is it fertile?`,
    options: [r`21 chromosomes, fertile because each set came from a parent`, r`21 chromosomes, sterile because three sets cannot pair evenly`, r`42 chromosomes, sterile because the sets are too many to pair`, r`14 chromosomes, fertile because the extra sets are discarded`],
    correctAnswer: 1,
    explanation: r`The diploid gives a gamete with 7 chromosomes and the tetraploid gives one with 14, so the offspring is a triploid with 21. Three sets cannot pair two by two in meiosis, so it is sterile, which isolates the tetraploid from its parent in one generation. The totals of 42 and 14 add or drop whole genomes instead of combining the two gametes.`,
  },
  [r`Sea urchin species broadcast gametes into the same water, yet hybrids are rare. Which reproductive barrier explains this?`]: {
    question: r`Males and females of two fruit fly species court and mate readily in the lab. However, sperm from a male of the other species die within the female's reproductive tract, and no eggs are fertilized. Which barrier is this?`,
    options: [r`Mechanical isolation, a prezygotic barrier`, r`Hybrid inviability, a postzygotic barrier`, r`Gametic isolation, a prezygotic barrier`, r`Behavioral isolation, a prezygotic barrier`],
    correctAnswer: 2,
    explanation: r`Mating and sperm transfer succeed, but the gametes never fuse, so this is gametic isolation and no zygote forms. Mechanical isolation would block sperm transfer, behavioral isolation would block courtship, and hybrid inviability requires a zygote that then fails.`,
  },
  [r`Mechanical isolation means {{c1::reproductive structures are physically incompatible}} — mismatched genitalia or flower architectures.`]: {
    question: r`One snail population has shells that coil to the left and another has shells that coil to the right. Snails from the two populations court each other, but because their bodies are mirror images their genital openings cannot be brought together. Which barrier is this?`,
    options: [r`Behavioral isolation, since courtship signals go unrecognized`, r`Gametic isolation, since the sperm cannot bind to the egg`, r`Mechanical isolation, since the body structures do not fit`, r`Temporal isolation, since the forms breed at different times`],
    correctAnswer: 2,
    explanation: r`The snails attempt to mate but are physically unable to transfer gametes, which is mechanical isolation. Courtship does occur, so the barrier is not behavioral; sperm never reach an egg, so it is not gametic; and nothing indicates different breeding times.`,
  },
  [r`The selection mode that produces a bimodal (two-peaked) trait distribution is {{c1::disruptive selection}}.`]: {
    question: r`A histogram of bill width in a seed-eating bird once had a single peak at 14 mm. After many generations it has two peaks, at 12 mm and 16 mm, with few birds at 14 mm. Which fitness pattern most likely produced this change?`,
    options: [r`Birds near 14 mm had the lowest fitness`, r`Birds near 14 mm had the highest fitness`, r`Birds near 16 mm alone had high fitness`, r`Birds of every width had equal fitness`],
    correctAnswer: 0,
    explanation: r`A two-peaked distribution arises from disruptive selection, in which intermediates do worst and both extremes do well. Highest fitness at 14 mm would narrow the curve around one peak, an advantage at 16 mm alone would shift a single peak, and equal fitness would leave the shape unchanged.`,
  },
  [r`Intersexual vs intrasexual selection: in each, who does the choosing or the competing?`]: {
    question: r`In a pipefish species, males carry the eggs and can brood only a few clutches, so males are choosy. Females are larger than males and carry bright stripes, and males pick the most striped females. The female stripes evolved by:`,
    options: [r`Intersexual selection, with females doing the choosing`, r`Intersexual selection, with males doing the choosing`, r`Intrasexual selection, with males competing for mates`, r`Intrasexual selection, with females fighting each other`],
    correctAnswer: 1,
    explanation: r`Intersexual selection is mate choice, and here the choosing sex is the male, so the ornament appears in females. The usual pattern of female choice is reversed in this species, and intrasexual selection would involve direct contests within one sex, which the scenario does not describe.`,
  },
  [r`Which selection mode can serve as the first step toward sympatric speciation, and why?`]: {
    question: r`In a lake fish, small-jawed and large-jawed individuals feed well while fish with intermediate jaws feed poorly, yet all the fish still interbreed freely. Which change would most directly move this population toward sympatric speciation?`,
    options: [r`Fish with intermediate jaws begin to feed as well as the rest`, r`A landslide divides the lake into two fully separate basins`, r`Fish begin mating mostly with partners of their own jaw type`, r`Fish begin mating entirely at random with respect to jaw type`],
    correctAnswer: 2,
    explanation: r`Disruptive selection creates two phenotype clusters, and assortative mating by phenotype then cuts gene flow between them without any barrier. Better feeding by intermediates would remove the disruptive selection, a landslide would make the split allopatric, and random mating keeps blending the two clusters.`,
  },
  [r`Hamilton's rule states that altruism is favored when {{c1::$rB > C$}}.`]: {
    question: r`An allele causes a bird to feed its nephews (r = 0.25). Each bout of feeding costs the bird 1 offspring of its own and lets the nephews' parents raise 3 extra offspring. Will the allele be favored?`,
    options: [r`Yes, because the benefit of 3 is more than the cost of 1`, r`Yes, because 0.5 × 3 = 1.5 is more than the cost of 1`, r`No, because 0.25 × 3 = 0.75 is less than the cost of 1`, r`No, because 0.25 × 1 = 0.25 is less than the benefit of 3`],
    correctAnswer: 2,
    explanation: r`Hamilton's rule requires rB > C. Here rB = 0.25 × 3 = 0.75, which is below C = 1, so the altruism is not favored. Comparing B with C directly drops relatedness, 0.5 is the wrong r for a nephew, and multiplying r by the cost applies the weighting to the wrong term.`,
  },
  [r`Coefficient of relatedness: full siblings r = 1/2; first cousins r = {{c1::1/8}}.`]: {
    question: r`At equal cost to itself, an animal can save either 3 of its full siblings or 10 of its first cousins. Which choice preserves more copies of its alleles?`,
    options: [r`The 10 cousins, since 10 × 1/4 = 2.5 beats 3 × 1/2 = 1.5`, r`The 3 siblings, since 3 × 1/2 = 1.5 beats 10 × 1/8 = 1.25`, r`The 10 cousins, since 10 × 1/8 = 1.25 beats 3 × 1/4 = 0.75`, r`The 3 siblings, since 3 × 1 = 3 beats 10 × 1/4 = 2.5`],
    correctAnswer: 1,
    explanation: r`Full siblings have r = 1/2 and first cousins have r = 1/8, so the siblings are worth 1.5 and the cousins 1.25. Using 1/4 for cousins is the half-sibling value, 1/4 for full siblings halves the true value, and r = 1 applies only to identical twins or clones.`,
  },
  [r`Peacock trains persist despite predation costs because sexual selection maximizes {{c1::reproductive success, even at the expense of survival}}.`]: {
    question: r`In a stream with predators, brightly colored male guppies live half as long as dull males but sire four times as many offspring per month while alive. What should happen to an allele for bright color?`,
    options: [r`It declines, since bright males have half the survival of dull`, r`It spreads, since bright males are better at evading predators`, r`It holds level, since mating gains cancel the survival losses`, r`It spreads, since bright males leave about twice the offspring`],
    correctAnswer: 3,
    explanation: r`Half the lifespan times four times the monthly rate gives about twice the lifetime offspring, and reproductive success is what selection counts. Lower survival alone does not decide the outcome, bright males are worse at evading predators here, and the gains do not cancel: 0.5 × 4 = 2.`,
  },
  [r`Inclusive fitness equals direct fitness from one's own offspring plus {{c1::indirect fitness through relatives' reproduction}}, weighted by relatedness.`]: {
    question: r`Animal X raises 3 offspring and helps no one. Animal Y raises 2 offspring, and its help lets its full sister raise 4 extra offspring. Weighting the sister's extra offspring by Y's relatedness to her (r = 0.5), which animal has the higher inclusive fitness?`,
    options: [r`Y, because 2 + (0.5 × 4) = 4 is greater than X's total of 3`, r`X, because 3 offspring of its own is more than Y's own 2`, r`Y, because 2 + 4 = 6 is greater than X's total of 3`, r`X, because its total of 3 is greater than Y's 0.5 × 4 = 2`],
    correctAnswer: 0,
    explanation: r`Inclusive fitness adds the direct component (own offspring) to the indirect component (relatives' extra offspring weighted by relatedness), so Y scores 2 + 2 = 4 against X's 3. Counting only own offspring ignores the indirect part, adding 4 unweighted ignores relatedness, and using only 0.5 × 4 leaves out Y's own offspring.`,
  },
  [r`Evolutionary fitness is defined strictly as {{c1::relative reproductive success — allele contribution to the next generation}}.`]: {
    question: r`In year 1, a genotype of beetle averages 4 surviving offspring while the other genotypes average 2. In year 5 it still averages 4, but the other genotypes now average 8. What has happened to this genotype's evolutionary fitness?`,
    options: [r`It held, because its own offspring number did not change`, r`It fell, because fitness is measured against other genotypes`, r`It rose, because the population as a whole now grows faster`, r`It held, because its survival to adulthood did not change`],
    correctAnswer: 1,
    explanation: r`Fitness is relative reproductive success: the genotype went from doubling its rivals' output to producing half of it, so its alleles now lose ground each generation. An unchanged absolute count or unchanged survival does not keep fitness constant, and faster growth of the whole population does not help a genotype that is being outreproduced.`,
  },
  [r`Apple maggot flies diverging on hawthorn vs apple hosts exemplify {{c1::sympatric speciation in progress via host (habitat) isolation}}.`]: {
    question: r`Apple maggot flies include a race that lays eggs on hawthorn fruit and a race that lays eggs on apples, with the two trees growing side by side. Why does the difference in host preference reduce gene flow between the races?`,
    options: [r`Flies court and mate on their host fruit, so host choice sorts mates`, r`The host trees grow in separate regions, so the races never meet`, r`Hybrid flies are always sterile, so crosses leave no descendants`, r`Apple flies are tetraploid, so their gametes cannot pair normally`],
    correctAnswer: 0,
    explanation: r`Because mating takes place on the preferred fruit, choosing a host also chooses a mate from the same race, giving habitat isolation without geographic separation. The trees grow side by side, hybrids are not sterile, and no polyploidy is involved; this is sympatric divergence by a host shift.`,
  },
  [r`A finch population's mean beak size increases steadily across drought years. Classify the selection and describe the graph change.`]: {
    question: r`For decades, fishing nets with a fixed mesh have caught large cod and let small cod escape, and body size in cod is heritable. How should a graph of the body-size distribution change over the generations?`,
    options: [r`The curve narrows around the original mean size`, r`The curve splits into two peaks at the extremes`, r`The whole curve shifts toward smaller body sizes`, r`The whole curve shifts toward larger body sizes`],
    correctAnswer: 2,
    explanation: r`Only one tail (large fish) is being removed, so the advantage lies in the other tail and the distribution moves that way: directional selection toward small size. Narrowing around the mean is stabilizing, two peaks is disruptive, and a shift toward large size has the direction of the advantage backwards.`,
  },
  [r`Two frog species share a pond, but one breeds in early spring and the other in midsummer. Name the barrier type.`]: {
    question: r`Two pine species grow mixed in one forest. One sheds pollen in February and the other in April, by which time the first species' cones are no longer receptive. Hand pollination in a greenhouse produces vigorous, fertile hybrids. Which barrier keeps the species separate in nature?`,
    options: [r`Hybrid sterility, a postzygotic barrier`, r`Habitat isolation, a prezygotic barrier`, r`Gametic isolation, a prezygotic barrier`, r`Temporal isolation, a prezygotic barrier`],
    correctAnswer: 3,
    explanation: r`The gametes are never available at the same time, so the barrier is temporal and acts before fertilization. Fertile greenhouse hybrids rule out hybrid sterility and gametic incompatibility, and the trees share one forest, so habitat is not what separates them.`,
  },
  [r`Female fireflies respond only to their own species' flash pattern. This prezygotic barrier is {{c1::behavioral isolation}}.`]: {
    question: r`Females of two lake fish species choose mates by male color, one species preferring blue males and the other red. Under orange lighting that hides the color difference, females mate with males of either species, and the hybrids are healthy and fertile. The barrier in normal light is:`,
    options: [r`Behavioral isolation, since mate recognition signals differ`, r`Mechanical isolation, since the mating structures do not fit`, r`Gametic isolation, since sperm and egg fail to fuse together`, r`Hybrid breakdown, since later hybrid generations are unfit`],
    correctAnswer: 0,
    explanation: r`The only thing keeping the species apart is a courtship signal, and removing it lets them hybridize, so the barrier is behavioral. Successful matings and fertile hybrids under orange light show that structures fit, gametes fuse, and hybrids are not unfit.`,
  },
  [r`A mule (horse x donkey) is healthy but sterile. Classify this reproductive barrier precisely.`]: {
    question: r`A cross between a zebra and a donkey produces an animal that is healthy and lives a normal lifespan but cannot make functional gametes. How is this reproductive barrier classified?`,
    options: [r`Hybrid sterility, a postzygotic barrier`, r`Hybrid inviability, a postzygotic barrier`, r`Hybrid breakdown, a postzygotic barrier`, r`Gametic isolation, a prezygotic barrier`],
    correctAnswer: 0,
    explanation: r`A zygote forms and develops into a healthy adult, so the barrier is postzygotic, and the failure is in gamete production, which is hybrid sterility. Inviability would mean the hybrid dies early, breakdown would mean a fertile first generation with unfit later generations, and gametic isolation would prevent the zygote from forming at all.`,
  },
  [r`Why do ground squirrels give alarm calls that raise their own risk of predation?`]: {
    question: r`A female ground squirrel gives alarm calls often when her daughters and sisters live in nearby burrows, but rarely when her only neighbors are unrelated squirrels. Calling raises her own risk in both cases. Which explanation does this pattern support?`,
    options: [r`Reciprocal altruism, since calling tracks past favors received`, r`Group selection, since calling protects the colony as a whole`, r`Sexual selection, since calling attracts more potential mates`, r`Kin selection, since calling tracks the presence of relatives`],
    correctAnswer: 3,
    explanation: r`A costly act directed mainly at relatives is what kin selection predicts, because the relatives saved carry copies of the caller's alleles. Reciprocity would track past help, not relatedness, group benefit would predict calling regardless of who is nearby, and the calls are warnings, not courtship.`,
  },
  [r`Relative fitness w and the selection coefficient s are related by {{c1::$s = 1 - w$}}.`]: {
    question: r`In a beetle population the fittest genotype leaves an average of 50 offspring. A second genotype has a selection coefficient of s = 0.3 against it. What is its relative fitness, and about how many offspring does it leave on average?`,
    options: [r`w = 0.3, so about 15 offspring`, r`w = 1.3, so about 65 offspring`, r`w = 0.4, so about 20 offspring`, r`w = 0.7, so about 35 offspring`],
    correctAnswer: 3,
    explanation: r`Since s = 1 − w, the relative fitness is w = 1 − 0.3 = 0.7, and 0.7 × 50 = 35 offspring. Setting w equal to s gives 15, adding s instead of subtracting gives 65, and 20 comes from subtracting 30 from 50 as if s were a count of offspring.`,
  },
  [r`What initiating event does allopatric speciation require?`]: {
    question: r`Which event could serve as the starting point for allopatric speciation in a forest beetle?`,
    options: [r`A chromosome doubling makes some of the beetles tetraploid`, r`A few beetles raft on driftwood to an island far offshore`, r`Some beetles begin feeding on a new host tree in the forest`, r`Females in the forest begin to prefer darker-colored males`],
    correctAnswer: 1,
    explanation: r`Allopatric speciation starts with geographic separation that blocks gene flow, and long-distance dispersal to an island does that. Polyploidy, a host shift and a change in mate preference all occur within the same forest, so they are routes to sympatric speciation instead.`,
  },
  [r`Speciation without geographic separation is {{c1::sympatric speciation}} — via polyploidy, host or habitat shifts, or strong sexual selection.`]: {
    question: r`Consider three cases: a tetraploid plant arising in a meadow of diploids, an insect race shifting to a new host tree in the same forest, and females in one lake diverging in which male color they prefer. What do these routes to speciation have in common?`,
    options: [r`Gene flow is cut by a physical barrier between two areas`, r`Gene flow continues while drift alone splits the species`, r`Gene flow is cut only after the populations move apart`, r`Gene flow is cut by a biological barrier within one area`],
    correctAnswer: 3,
    explanation: r`All three are sympatric speciation: polyploidy, a host shift and divergent mate choice each sever gene flow by biological means in a single location. A physical barrier or populations moving apart describes allopatric speciation, and speciation cannot complete while gene flow continues freely.`,
  },
  [r`Hybrid breakdown differs from other postzygotic barriers because {{c1::the F1 is viable and fertile, but F2 or backcross generations fail}}.`]: {
    question: r`Two copepod populations are crossed. The first-generation hybrids survive and reproduce as well as either parent, but the second-generation hybrids have half the survival. What best explains why the problem appears only in the second generation?`,
    options: [r`The F1 has an odd chromosome number that blocks its meiosis`, r`The F1 sperm cannot bind to eggs of either parental population`, r`Recombination in the F1 creates incompatible gene combinations`, r`The F1 embryos die before they can reach reproductive age`],
    correctAnswer: 2,
    explanation: r`This is hybrid breakdown: the F1 carries one complete genome from each parent and works well, but recombination shuffles the two genomes, so F2 individuals inherit mismatched combinations. A blocked meiosis, failed sperm binding or early death would each stop the F1 from reproducing, and the F1 here is fully fertile.`,
  },
  [r`Under negative frequency-dependent selection, an allele's fitness {{c1::decreases}} as it becomes common.`]: {
    question: r`A rare immune-system allele protects its carriers well because local parasites have not adapted to evade it. Over time the allele spreads until 70% of hosts carry it. Under negative frequency-dependent selection, what happens to its fitness advantage?`,
    options: [r`It grows, since more hosts now carry the protective allele`, r`It holds steady, since the allele's protein has not changed`, r`It shrinks, since parasites adapt to the now common allele`, r`It shrinks, since common alleles pick up more mutations`],
    correctAnswer: 2,
    explanation: r`Under negative frequency dependence an allele's fitness falls as it becomes common: parasites are selected to evade whichever host type is most abundant. The advantage does not grow with frequency or stay fixed just because the protein is unchanged, and the loss has nothing to do with mutation load in common alleles.`,
  },
  [r`How does artificial selection differ mechanistically from natural selection?`]: {
    question: r`A breeder keeps only the wheat plants with the largest grains for seed. In a nearby grassland, a long drought leaves mostly deep-rooted wild grasses alive to set seed. Which statement correctly compares the two processes?`,
    options: [r`Only the breeder's process depends on heritable variation`, r`Only the drought's process changes the allele frequencies`, r`Both work by inducing new mutations for the favored trait`, r`Both work by differential reproduction of heritable variants`],
    correctAnswer: 3,
    explanation: r`Artificial and natural selection share one mechanism: some heritable variants reproduce more than others, and only the selecting agent differs. Both need heritable variation and both change allele frequencies, and neither induces the mutations it favors.`,
  },
  [r`What long-term advantage does sexual reproduction provide despite its twofold cost?`]: {
    question: r`In a small asexual lineage, the individuals carrying the fewest harmful mutations happen to die without reproducing, and the lineage never regains a genome that clean. Why can a sexual population recover from the same loss?`,
    options: [r`Sexual lineages have a lower mutation rate in each generation`, r`Recombination can rebuild genomes with fewer harmful mutations`, r`Sexual lineages produce twice as many offspring per parent`, r`Recombination stops new harmful mutations from ever arising`],
    correctAnswer: 1,
    explanation: r`Without recombination, the least-loaded class cannot be recreated once lost, so harmful mutations ratchet upward; sex can combine mutation-free regions from two parents into one genome. Sex does not lower the mutation rate or prevent mutations, and it carries a twofold cost in offspring rather than a twofold gain.`,
  },
  [r`Contrast the reproductive strategies favored in unstable versus saturated environments.`]: {
    question: r`A small crustacean lives in desert pools that fill after rare storms, are almost never crowded, and dry up unpredictably within a few weeks. Which set of life-history traits should selection favor in this species?`,
    options: [r`Late maturity, few large offspring, long parental care`, r`Early maturity, few large offspring, long parental care`, r`Early maturity, many small offspring, little parental care`, r`Late maturity, many small offspring, little parental care`],
    correctAnswer: 2,
    explanation: r`Unstable, uncrowded habitats favor r-selected traits: breed early and produce many cheap offspring before the pool disappears. Late maturity and heavy investment in a few offspring are K-selected traits suited to stable habitats near carrying capacity, and the mixed sets pair traits that do not fit this environment.`,
  },
  [r`Evolutionary fitness is defined by {{c1::relative reproductive success}}, not by survival, size, or strength.`]: {
    question: r`A mutation doubles a fish's lifespan and body size but makes it completely sterile. What is the evolutionary fitness of a fish carrying this mutation?`,
    options: [r`High, because it outlives every competitor in the pond`, r`Zero, because it passes no alleles to the next generation`, r`High, because a larger body wins more contests over food`, r`Average, because survival gains offset the lost offspring`],
    correctAnswer: 1,
    explanation: r`Fitness is reproductive success, so an organism that leaves no offspring has zero fitness however long it lives or however large it grows. Survival and size matter only as they feed reproduction, so they cannot raise fitness or offset sterility.`,
  },
  [r`Why does selection act on phenotypes yet only heritable variation produces evolutionary change?`]: {
    question: r`A self-fertilizing bean line is genetically uniform, yet its plants vary in height because the soil is uneven. A gardener saves seed only from the tallest plants each year for 10 years, sowing on the same uneven soil. What happens to mean height?`,
    options: [r`It stays the same, since the height differences are not heritable`, r`It rises each year, since only the tallest plants are chosen`, r`It rises at first, then levels off as the variation is used up`, r`It falls, since tall plants pass on fewer copies of their alleles`],
    correctAnswer: 0,
    explanation: r`Selection acts on the phenotype, so the gardener really does pick tall plants, but those plants are genetically identical to the short ones and pass on nothing different. With no heritable variation there is no response at all, not a steady rise, an initial rise, or a fall.`,
  },
  [r`If AA leaves 100 offspring and aa leaves 80, then aa has relative fitness $0.8$ and selection coefficient {{c1::$s = 0.2$}}.`]: {
    question: r`In a moth population, genotypes BB and Bb each leave an average of 200 offspring, and genotype bb leaves an average of 150. What is the selection coefficient against bb?`,
    options: [r`s = 0.75, since w = 150/200 = 0.75 and s = w`, r`s = 0.33, since (200 − 150)/150 = 0.33`, r`s = 50, since 200 − 150 = 50 offspring`, r`s = 0.25, since w = 150/200 = 0.75 and s = 1 − w`],
    correctAnswer: 3,
    explanation: r`Relative fitness is scaled to the most successful genotype, so w = 150/200 = 0.75 and s = 1 − 0.75 = 0.25. Reporting 0.75 gives the fitness itself, 0.33 divides the deficit by the wrong genotype's output, and 50 is an absolute difference, not a proportion.`,
  },
  [r`Vampire bats share blood with unrelated roostmates who previously fed them. Kin selection or reciprocal altruism?`]: {
    question: r`Unrelated male baboons A and B live in one troop. A helps B in a fight; weeks later B is more likely to help A, and both refuse to help males who have not helped them. Which explanation fits, and what does it require?`,
    options: [r`Kin selection, which needs a high relatedness between the two males`, r`Reciprocal altruism, which needs repeated meetings and recognition`, r`Reciprocal altruism, which needs the helper and recipient to be kin`, r`Kin selection, which needs repeated meetings and recognition`],
    correctAnswer: 1,
    explanation: r`Help exchanged between non-relatives and conditional on past help is reciprocal altruism, which works only when individuals meet repeatedly, recognize each other and can withhold help from cheaters. Kin selection needs shared genes, which unrelated males lack, and reciprocity does not require kinship.`,
  },
  [r`Why does haplodiploidy in bees and ants favor sterile worker castes?`]: {
    question: r`In a haplodiploid ant species, a worker has the same father as her sisters. With the same effort, she could either help rear 4 full sisters or produce 4 offspring of her own. Which option passes on more copies of her alleles?`,
    options: [r`Having offspring, since 4 × 0.5 = 2 exceeds 4 × 0.25 = 1`, r`Neither, since 4 × 0.5 = 2 for sisters and offspring alike`, r`Having offspring, since 4 × 1 = 4 exceeds 4 × 0.75 = 3`, r`Rearing sisters, since 4 × 0.75 = 3 exceeds 4 × 0.5 = 2`],
    correctAnswer: 3,
    explanation: r`Haploid fathers give every daughter the same sperm genome, so full sisters share r = 0.75, more than the 0.5 a female shares with her own offspring. Using 0.5 or 0.25 for sisters applies diploid sibling or half-sibling values, and an offspring is never related to its mother by 1.`,
  },
  [r`Male deer fighting for access to females is {{c1::intrasexual}} selection, while peahen choice of tail displays is intersexual.`]: {
    question: r`Male stag beetles use enlarged jaws to throw rival males off a feeding branch. Females mate with whichever male holds the branch and, in choice tests, show no preference among males of different jaw size. The enlarged jaws evolved by:`,
    options: [r`Intersexual selection, since females end up with the winner`, r`Intersexual selection, since the trait differs between sexes`, r`Natural selection alone, since large jaws improve feeding`, r`Intrasexual selection, since males compete with each other`],
    correctAnswer: 3,
    explanation: r`Weapons used in contests between members of the same sex are products of intrasexual selection. Intersexual selection requires mate choice, which the choice tests rule out, and a sex difference alone does not show choice. The jaws are used for fighting rivals, not for feeding.`,
  },
  [r`How can a costly ornament like a peacock's tail be an honest signal of quality?`]: {
    question: r`In a bird species, males with the longest tails carry the fewest parasites, and their offspring survive best. Experimentally shortening a male's tail does not change his parasite load. Which interpretation fits best?`,
    options: [r`Tail length causes health, since long feathers repel the parasites`, r`Tail length is unrelated to quality and varies by chance alone`, r`Tail length reveals quality, since only healthy males can afford it`, r`Tail length reveals quality, since long tails cost nothing to grow`],
    correctAnswer: 2,
    explanation: r`Under the handicap principle a costly ornament is an honest signal because only high-quality males can bear it, which explains the link with low parasite load and offspring survival. The shortening experiment shows the tail does not cause health, the correlation rules out chance alone, and a cost-free tail could be faked by weak males.`,
  },
  [r`Sickle cell in malarial regions is the standard example of which selection mode, and what is its signature?`]: {
    question: r`In rats exposed to a poison, SS rats die from the poison, RR rats resist it but have a severe vitamin K deficiency, and RS rats resist it with only a mild deficiency and leave the most offspring. What is the expected long-term fate of allele R while the poison is in use?`,
    options: [r`It settles at a stable intermediate frequency`, r`It rises until it is fixed in the population`, r`It falls until it is lost from the population`, r`It drifts at random with no predictable end`],
    correctAnswer: 0,
    explanation: r`The heterozygote is fittest, so selection keeps both alleles in the population, as with the sickle cell allele where malaria is common. The signature is a stable intermediate frequency. Fixation or loss is what directional selection produces, and a consistent fitness difference makes the outcome predictable, unlike drift.`,
  },
  [r`Adaptation requires {{c1::preexisting}} heritable variation; environments do not induce the mutations they favor.`]: {
    question: r`An unusually cold decade hits two isolated lizard populations of equal size. Population 1 carries cold-tolerance alleles at low frequency. Population 2 has none. What is the most likely outcome?`,
    options: [r`Only population 1 adapts, since it already holds the needed alleles`, r`Both adapt, since cold induces tolerance mutations where needed`, r`Only population 2 adapts, since it faces the stronger selection`, r`Neither adapts, since selection cannot alter allele frequencies`],
    correctAnswer: 0,
    explanation: r`Selection can only sort variation that already exists, so the population with standing cold-tolerance alleles can respond while the other may decline. Cold does not induce the mutations it would favor, strong selection without variation produces no response, and selection certainly changes allele frequencies when variation is present.`,
  },
  [r`Resistant bacteria often decline once the antibiotic is removed. What does this reveal about fitness?`]: {
    question: r`A resistant and a sensitive bacterial strain are mixed 50:50. In drug-free medium the resistant strain falls to 5% of the culture after 100 generations, with no new mutations detected. In medium containing the antibiotic it reaches 100%. What do the results show?`,
    options: [r`Resistant cells revert to sensitive once the drug is removed`, r`Resistance is the fitter state in every environment over time`, r`Fitness depends on environment, and resistance carries a cost`, r`Fitness depends on cell numbers, and sensitivity carries a cost`],
    correctAnswer: 2,
    explanation: r`The same genotype wins with the drug and loses without it, so fitness is not absolute; without the drug, the cost of the resistance mechanism lets sensitive cells outcompete resistant ones. No new mutations were detected, so reversion is not the cause, and the drug-free result contradicts resistance being superior everywhere.`,
  },
  [r`Antibiotic resistance spreading through a hospital population is an example of {{c1::directional}} selection observed in real time.`]: {
    question: r`Over five years of heavy antibiotic use on a hospital ward, the bacteria isolated from patients become steadily more resistant. Which description of the change in the bacterial population is accurate?`,
    options: [r`Mean resistance stays put while its variance gets smaller`, r`Each cell raises its own resistance during its own lifetime`, r`Mean resistance rises as the susceptible cells are removed`, r`Both highly resistant and highly susceptible cells increase`],
    correctAnswer: 2,
    explanation: r`This is directional selection: the drug removes one tail of the distribution, so the population mean moves toward higher resistance. An unchanged mean with less variance is stabilizing selection, an increase in both extremes is disruptive selection, and individual cells do not adapt on demand; the population changes because of who survives.`,
  },
  [r`An allele rises in frequency in all ten replicate populations under one condition. Selection or drift?`]: {
    question: r`Twelve fly populations each start with allele T at a frequency of 0.5. After 50 generations, the six kept at high temperature all have T between 0.85 and 0.95. The six control populations are scattered between 0.3 and 0.7. What is the best interpretation?`,
    options: [r`Drift favors T in the heat; the controls show selection alone`, r`Selection favors T in both the heated and the control lines`, r`Drift alone explains both the heated and the control lines`, r`Selection favors T in the heat; the controls show drift alone`],
    correctAnswer: 3,
    explanation: r`Parallel change in every independent replicate indicates a consistent fitness advantage, which is selection, while the controls wander in both directions as drift predicts. Drift has no direction, so it cannot push six separate lines the same way, and selection for T in the controls would not leave some of them below 0.5.`,
  },
  [r`Why do biologists reject naive group selection explanations such as animals limiting births for the good of the species?`]: {
    question: r`In a bird population every female lays 3 eggs, although each could successfully raise 5. An observer claims the birds hold back to keep the species from overpopulating. A mutant female that lays and raises 5 then appears. What happens to her allele?`,
    options: [r`It is lost, because selection protects the good of the species`, r`It spreads, because its carriers out-reproduce restrained birds`, r`It is lost, because the population then outgrows its food supply`, r`It spreads, because larger clutches benefit the whole population`],
    correctAnswer: 1,
    explanation: r`Selection acts fastest on individuals, so a variant that leaves more offspring spreads even if the group ends up worse off, which is why restraint for the good of the species is not stable. Selection does not guard species welfare or look ahead to food shortages, and the allele spreads because of its carriers' success, not any benefit to the population.`,
  },
}
